#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

REPO_ROOT="$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
ENV_FILE="${TMPDIR:-/tmp}/once-qa-tailscale-vaultwarden.env"

banner "Once — Tailscale + Vaultwarden manual QA"

# ── Stage 1: mode & namespace ──────────────────────────────────────────────
stage "Mode & namespace"
say "This walks the critical Tailscale + Vaultwarden journeys: enable Tailscale,"
say "deploy Vaultwarden exposed on your tailnet, verify it, back it up, restore it."
if ! docker info >/dev/null 2>&1; then
  warn "Docker doesn't seem to be running — start it before continuing."
  pause
fi
while true; do
  ask MODE "Clean install (fresh throwaway namespace) or reuse existing setup? [clean/existing]:"
  case "$MODE" in clean|existing) break ;; esac
  warn "type 'clean' or 'existing'"
done
if [[ "$MODE" == clean ]]; then
  ask NAMESPACE "Throwaway namespace name (destroyed and recreated):"
  : "${NAMESPACE:=once-qa}"
else
  ask NAMESPACE "Namespace of the existing setup to test against:"
  : "${NAMESPACE:=once}"
fi
write_env MODE "$MODE"
write_env NAMESPACE "$NAMESPACE"

# ── Stage 2: prerequisites ─────────────────────────────────────────────────
stage "Prerequisites"
say "Building the once binary."
( cd "$REPO_ROOT" && make build )
BIN="$REPO_ROOT/bin/once"
[[ -x "$BIN" ]] || { warn "build failed — $BIN not found"; exit 1; }
say "Using binary: $BIN"
if [[ "$MODE" == clean ]]; then
  say "Clearing any prior state in namespace '$NAMESPACE' (safe even if it doesn't exist yet)."
  "$BIN" -n "$NAMESPACE" teardown --remove-data >/dev/null 2>&1 || true
fi
pause "Ready to continue?"

# ── Stage 3: Tailscale — check current state ───────────────────────────────
stage "Tailscale — check current state"
TS_STATUS="$("$BIN" -n "$NAMESPACE" tailscale status 2>&1 || true)"
SKIP_TS_ENABLE=no
if printf '%s' "$TS_STATUS" | grep -q "^Topology:"; then
  say "Tailscale is already enabled on '$NAMESPACE':"
  printf '%s\n' "$TS_STATUS"
  if confirm "Use it as-is and skip the OAuth credential steps?"; then SKIP_TS_ENABLE=yes; fi
else
  say "Tailscale is not enabled yet on '$NAMESPACE'."
fi

# ── Stage 4: Tailscale — admin console + enable ────────────────────────────
stage "Tailscale — admin console + enable"
if [[ "$SKIP_TS_ENABLE" == yes ]]; then
  note "Skipping — Tailscale already enabled."
else
  say "Printing the policy snippet for the 'nodes' topology (Once's default)."
  "$BIN" -n "$NAMESPACE" tailscale policy --topology nodes
  open_url "https://login.tailscale.com/admin/acls"
  step "Merge the printed snippet into the policy file above, then save."
  pause "Merged the policy?"
  open_url "https://login.tailscale.com/admin/settings/trust-credentials"
  step "Credential → OAuth → Write scopes: Keys/Auth Keys, Devices/Core, Services → tag tag:once → Generate credential."
  step "Copy the Client ID (e.g. k123...CNTRL) and Client secret (tskey-client-...) — the secret is shown once."
  ask TS_CLIENT_ID "Client ID:"
  ask_secret TS_CLIENT_SECRET "Client secret (hidden, never saved to disk):"
  write_env TS_CLIENT_ID "$TS_CLIENT_ID"
  say "Enabling Tailscale (nodes topology)..."
  ONCE_TAILSCALE_CLIENT_SECRET="$TS_CLIENT_SECRET" "$BIN" -n "$NAMESPACE" tailscale enable --client-id "$TS_CLIENT_ID" --topology nodes
fi

# ── Stage 5: deploy Vaultwarden, tailnet-exposed ───────────────────────────
stage "Deploy Vaultwarden — tailnet exposure"
if "$BIN" -n "$NAMESPACE" status vaultwarden >/dev/null 2>&1; then
  note "vaultwarden is already deployed in '$NAMESPACE' — skipping deploy."
else
  say "Deploying Vaultwarden, exposed only on your tailnet, marked for auto-backup."
  "$BIN" -n "$NAMESPACE" deploy vaultwarden --expose tailnet --auto-backup
fi

# ── Stage 6: verify tailnet reachability ───────────────────────────────────
stage "Verify — tailnet reachability"
STATUS_LINE="$("$BIN" -n "$NAMESPACE" status vaultwarden)"
say "$STATUS_LINE"
URL="$(printf '%s\n' "$STATUS_LINE" | grep -oE 'https://[^[:space:]]+' | head -1)"
if [[ -z "$URL" ]]; then
  warn "no tailnet URL yet — the tailnet may still be spinning up; re-run \`once -n $NAMESPACE status vaultwarden\` in a moment."
else
  open_url "$URL"
fi
step "Confirm the Vaultwarden page loads over your tailnet."
step "Register a test account, log in, add one throwaway vault item — the restore drill checks for this."
pause "Done?"
note "Sanity check: from a device NOT on this tailnet, $URL should not resolve or load at all."

# ── Stage 7: backups — configure ───────────────────────────────────────────
stage "Backups — configure"
BACKUP_STATUS="$("$BIN" -n "$NAMESPACE" backup status)"
if printf '%s\n' "$BACKUP_STATUS" | grep -q "^Backups: enabled"; then
  note "Backups already enabled — skipping configuration."
else
  ask BACKUP_LOCAL_PATH "Local backup repo path (created if missing):"
  : "${BACKUP_LOCAL_PATH:=/tmp/once-qa-backups/$NAMESPACE}"
  mkdir -p "$BACKUP_LOCAL_PATH"
  write_env BACKUP_LOCAL_PATH "$BACKUP_LOCAL_PATH"
  "$BIN" -n "$NAMESPACE" backup enable --local-path "$BACKUP_LOCAL_PATH" --password-delivery screen
  warn "save the Recovery Kit password printed above somewhere off this machine — shown once."
  pause "Saved it?"
fi
BACKUP_LOCAL_PATH="$("$BIN" -n "$NAMESPACE" backup status | awk -F'Local repository:' '/Local repository:/{gsub(/^[ \t]+/,"",$2); print $2; exit}')"

# ── Stage 8: backups — run one cycle ───────────────────────────────────────
stage "Backups — run one cycle"
say "Starting the background runner to produce Vaultwarden's first snapshot."
note "A never-backed-up app is immediately due, so this should land on the first check (~5 min)."
"$BIN" -n "$NAMESPACE" background run >"${TMPDIR:-/tmp}/once-qa-background.log" 2>&1 &
BG_PID=$!
FOUND=no
for _ in $(seq 1 24); do
  if "$BIN" -n "$NAMESPACE" restore vaultwarden --repo "$BACKUP_LOCAL_PATH" --list 2>/dev/null | grep -qE '^  [0-9a-f]+'; then
    FOUND=yes
    break
  fi
  sleep 15
done
kill "$BG_PID" 2>/dev/null || true
wait "$BG_PID" 2>/dev/null || true
if [[ "$FOUND" == yes ]]; then
  say "Snapshot found:"
  "$BIN" -n "$NAMESPACE" restore vaultwarden --repo "$BACKUP_LOCAL_PATH" --list
else
  warn "no snapshot after ~6 minutes — check ${TMPDIR:-/tmp}/once-qa-background.log"
  pause "Investigate, then press Enter to continue anyway"
fi

# ── Stage 9: restore drill ──────────────────────────────────────────────────
stage "Restore drill"
if confirm "Remove Vaultwarden (data included) to simulate loss, then restore from the backup repo?"; then
  "$BIN" -n "$NAMESPACE" remove vaultwarden --remove-data
  "$BIN" -n "$NAMESPACE" restore vaultwarden --repo "$BACKUP_LOCAL_PATH"
  STATUS_LINE="$("$BIN" -n "$NAMESPACE" status vaultwarden)"
  say "$STATUS_LINE"
  URL="$(printf '%s\n' "$STATUS_LINE" | grep -oE 'https://[^[:space:]]+' | head -1)"
  [[ -n "$URL" ]] && open_url "$URL"
  step "Log in with the test account and confirm the vault item you added earlier is still there."
  pause "Confirmed?"
else
  note "Skipped."
fi

# ── Stage 10: optional Funnel check ────────────────────────────────────────
stage "Optional — Funnel (temporary public access)"
if confirm "Test Funnel too? (temporarily makes Vaultwarden reachable from the public internet)"; then
  "$BIN" -n "$NAMESPACE" tailscale funnel enable vaultwarden --duration 5m
  "$BIN" -n "$NAMESPACE" tailscale status
  step "From a device off your tailnet (e.g. phone on cellular), open the Funnel URL above."
  pause "Confirmed reachable publicly?"
  "$BIN" -n "$NAMESPACE" tailscale funnel disable vaultwarden
  step "Re-check that the Funnel URL now fails from off-tailnet (may take a moment to propagate)."
  pause "Confirmed it's gone?"
else
  note "Skipped."
fi

# ── Stage 11: cleanup ───────────────────────────────────────────────────────
stage "Cleanup"
if confirm "Tear down the QA namespace '$NAMESPACE' now (removes containers + volumes)?"; then
  "$BIN" -n "$NAMESPACE" teardown --remove-data
fi
if [[ -n "${TS_CLIENT_ID:-}" && "$SKIP_TS_ENABLE" == no ]]; then
  note "If that OAuth credential was throwaway, revoke it: https://login.tailscale.com/admin/settings/trust-credentials"
fi

finish
